// CodeMirror Markdown mode (simplified)
CodeMirror.defineMode("markdown", function(cmCfg, modeCfg) {
  var htmlMode = CodeMirror.getMode(cmCfg, "text/html");
  var htmlModeMissing = htmlMode.name == "null";

  function getMode(name) {
    if (CodeMirror.findModeByName) {
      var found = CodeMirror.findModeByName(name);
      if (found) name = found.mime || found.mimes[0];
    }
    var mode = CodeMirror.getMode(cmCfg, name);
    return mode.name == "null" ? null : mode;
  }

  if (modeCfg.highlightFormatting === undefined)
    modeCfg.highlightFormatting = false;

  return CodeMirror.overlayMode(CodeMirror.getMode(cmCfg, "text/plain"), {
    startState: function() {
      return {
        code: false,
        codeBlock: false,
        ateSpace: false,
        inLink: false
      };
    },
    token: function(stream, state) {
      if (stream.sol()) {
        state.ateSpace = false;
      }

      // Code blocks
      if (stream.match(/^```/)) {
        state.codeBlock = !state.codeBlock;
        return "comment";
      }
      if (state.codeBlock) {
        stream.skipToEnd();
        return "comment";
      }

      // Headers
      if (stream.sol() && stream.match(/^#{1,6}/)) {
        stream.skipToEnd();
        return "header";
      }

      // Bold
      if (stream.match(/\*\*/)) {
        return "strong";
      }

      // Italic
      if (stream.match(/\*/)) {
        return "em";
      }

      // Inline code
      if (stream.match(/`/)) {
        if (!state.code) {
          state.code = true;
          return "comment";
        } else {
          state.code = false;
          return "comment";
        }
      }
      if (state.code) {
        stream.next();
        return "comment";
      }

      // Links
      if (stream.match(/\[.*?\]\(.*?\)/)) {
        return "link";
      }

      // Lists
      if (stream.sol() && (stream.match(/^\s*[\*\-\+]\s/) || stream.match(/^\s*\d+\.\s/))) {
        return "string";
      }

      stream.next();
      return null;
    }
  });
});

CodeMirror.defineMIME("text/x-markdown", "markdown");